const fs = require('fs');

const filename = process.argv[2] || '/app/a.out';
const buf = fs.readFileSync(filename);

// Read ELF header for 64-bit
const e_phoff = Number(buf.readBigUInt64LE(32));
const e_phentsize = buf.readUInt16LE(54);
const e_phnum = buf.readUInt16LE(56);

const baseAddr = 0x400000;
const result = {};

for (let i = 0; i < e_phnum; i++) {
    const phOffset = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(phOffset);
    if (p_type === 1) { // PT_LOAD
        const p_offset = Number(buf.readBigUInt64LE(phOffset + 8));
        const p_vaddr = Number(buf.readBigUInt64LE(phOffset + 16));
        const p_filesz = Number(buf.readBigUInt64LE(phOffset + 32));
        const p_memsz = Number(buf.readBigUInt64LE(phOffset + 40));

        const startAddr = baseAddr + p_vaddr;

        for (let off = 0; off < p_memsz; off += 4) {
            const addr = startAddr + off;
            let val = 0;
            if (off < p_filesz) {
                if (off + 4 <= p_filesz) {
                    val = buf.readUInt32LE(p_offset + off);
                } else {
                    // partial bytes at the end of file content
                    for (let b = 0; b < (p_filesz - off); b++) {
                        val |= buf[p_offset + off + b] << (8 * b);
                    }
                }
            } else {
                val = 0; // BSS / zero-filled
            }
            result[addr.toString()] = val;
        }
    }
}

